content.query:
let ev = customEvents;
let visits = toscalar(ev | where name == "AppOpen" | count);
let visitors = toscalar(ev | where name == "AppOpen" | summarize dcount(user_Id));
let uses = toscalar(ev | where name != "AppOpen" | count);
datatable(Order:int, Metric:string)[1, "Visits", 2, "Visitors", 3, "Feature uses"]
| extend Value = case(Order == 1, visits, Order == 2, visitors, uses)
| order by Order asc
| project Metric, Value
